WITH with_windows AS (SELECT id, product_name, category, cost, tags, SUM(cost) OVER w_grp AS last4_sum_cost, COUNT(cost) OVER w_grp AS last4_count_cost, MAX(cost) OVER w_grp AS last4_max_cost, AVG(cost) OVER w_grp AS last4_avg_cost FROM products WINDOW w_grp AS (PARTITION BY category ORDER BY price ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT id, product_name, category, cost, last4_max_cost, last4_avg_cost, CASE WHEN product_name RLIKE '^(USB-C Hub|Desk Lamp)$' THEN 'CORE' ELSE 'EXTENDED' END AS product_name_zone FROM with_windows ORDER BY id ASC NULLS LAST;
